package android.os; public class Binder implements IBinder { public static int callingUid=0; public boolean isBinderAlive(){return true;} public void linkToDeath(DeathRecipient d,int f)throws RemoteException{} public boolean unlinkToDeath(DeathRecipient d,int f){return true;} public static int getCallingUid(){return callingUid;} protected boolean onTransact(int c,Parcel d,Parcel r,int f)throws RemoteException{return false;} public boolean transact(int c,Parcel d,Parcel r,int f)throws RemoteException{return onTransact(c,d,r,f);} }
